create or replace view IDQ_PRODUCTION.EKS_CALCULATION.SVMARA_EKS_ITEM_DQ_EKS_PALLETUTILISATIONUNDER50OROVER120_SEL(
	NEGOTIATINGCOUNTRY,
	BUYERSHORTSIGN,
	BUYERFIRSTNAME,
	BUYERLASTNAME,
	ZMATKL,
	ARTICLEFAMILY,
	ITEMID,
	ITEMNO,
	ARTICLETYPE,
	DESCRIPTION,
	DECIMALCASESIZE,
	CASEDEPTH,
	CASEWIDTH,
	CASEHEIGHT,
	USAGE,
	LISTINGOVERVIEWID,
	SUPPLIERNO,
	SUPPLIERDESCRIPTION,
	RECEIVINGCOUNTRY,
	ZRELEVANTMDM,
	ZSOURCE,
	ZACTIVE
) as
(WITH cte AS (SELECT DISTINCT EKS_CALCULATION.stMARA_EKS_ITEM.zNegotiatingCountry AS NegotiatingCountry, EKS_CALCULATION.stMARA_EKS_ITEM.BuyerSHORTSIGN, EKS_CALCULATION.stMARA_EKS_ITEM.BuyerFirstName, EKS_CALCULATION.stMARA_EKS_ITEM.BuyerLastName, EKS_CALCULATION.stMARA_EKS_ITEM.ArticleFamily, EKS_CALCULATION.stMARA_EKS_ITEM.zMATKL, EKS_CALCULATION.stMARA_EKS_ITEM.ITEMID, EKS_CALCULATION.stMARA_EKS_ITEM.ITEMNO, EKS_CALCULATION.stMARA_EKS_ITEM.zArticleType AS ArticleType,EKS_CALCULATION.stMARA_EKS_ITEM.DESCRIPTION_INT, bp.casesize, bp.DecimalCaseSize, struc.EA_ITEMNO, struc.EA_DESCRIPTION, struc.SK_ITEMNO, struc.SK_Description, struc.BA_ITEMNO, struc.BA_Description, bp.LISTINGOVERVIEWID, bp.SUPPLIERNO, bp.ReceivingCountry, bp.CONTRACTPRICEVALIDITYID, bp.zIsWAWIRelevant AS zRelevantMDM, EKS_CALCULATION.stMARA_EKS_ITEM.zSource, EKS_CALCULATION.stMARA_EKS_ITEM.zActive
 FROM      EKS_CALCULATION.stMARA_EKS_ITEM INNER JOIN
EKS_CALCULATION.xtEKS_BASICINFO_RecCountry AS bp ON bp.itemid = EKS_CALCULATION.stMARA_EKS_ITEM.ITEMID AND bp.SK_ITEMNO IS NULL INNER JOIN
EKS_CALCULATION.svMARA_EKS_ITEM_BASKEA_Structure_010 AS struc ON EKS_CALCULATION.stMARA_EKS_ITEM.ITEMNO = struc.EA_ITEMNO AND EKS_CALCULATION.stMARA_EKS_ITEM.zArticleType = 'EA' AND EKS_CALCULATION.stMARA_EKS_ITEM.zIsCurrentContract = 1 where  struc.SK_ITEMNO IS NULL
  UNION
SELECT DISTINCT EKS_CALCULATION.stMARA_EKS_ITEM.zNegotiatingCountry AS NegotiatingCountry, EKS_CALCULATION.stMARA_EKS_ITEM.BuyerSHORTSIGN, EKS_CALCULATION.stMARA_EKS_ITEM.BuyerFirstName, EKS_CALCULATION.stMARA_EKS_ITEM.BuyerLastName,EKS_CALCULATION.stMARA_EKS_ITEM.ArticleFamily, EKS_CALCULATION.stMARA_EKS_ITEM.zMATKL, EKS_CALCULATION.stMARA_EKS_ITEM.ITEMID, EKS_CALCULATION.stMARA_EKS_ITEM.ITEMNO, EKS_CALCULATION.stMARA_EKS_ITEM.zArticleType AS ArticleType, EKS_CALCULATION.stMARA_EKS_ITEM.DESCRIPTION_INT, bp.casesize, bp.DecimalCaseSize, struc.EA_ITEMNO, struc.EA_DESCRIPTION, struc.SK_ITEMNO, struc.SK_Description, struc.BA_ITEMNO, struc.BA_Description,bp.LISTINGOVERVIEWID, bp.SUPPLIERNO, bp.ReceivingCountry, bp.CONTRACTPRICEVALIDITYID, bp.zIsWAWIRelevant AS zRelevantMDM, EKS_CALCULATION.stMARA_EKS_ITEM.zSource, EKS_CALCULATION.stMARA_EKS_ITEM.zActive
FROM     EKS_CALCULATION.stMARA_EKS_ITEM INNER JOIN
EKS_CALCULATION.xtEKS_BASICINFO_RecCountry AS bp ON bp.SK_ITEMID = EKS_CALCULATION.stMARA_EKS_ITEM.ITEMID INNER JOIN
EKS_CALCULATION.svMARA_EKS_ITEM_BASKEA_Structure_010 AS struc ON EKS_CALCULATION.stMARA_EKS_ITEM.ITEMNO = struc.SK_ITEMNO AND EKS_CALCULATION.stMARA_EKS_ITEM.zArticleType = 'SK' AND EKS_CALCULATION.stMARA_EKS_ITEM.zIsCurrentContract = 1)

SELECT DISTINCT  cte.NegotiatingCountry, cte.BuyerSHORTSIGN, cte.BuyerFirstName, cte.BuyerLastName, cte.zMATKL, cte.ArticleFamily, cte.ITEMID, cte.ITEMNO, cte.ArticleType, cte.DESCRIPTION_INT as Description, cte.DecimalCaseSize, ITD.CASEDEPTH, ITD.CASEWIDTH, ITD.CASEHEIGHT, (EKS.ITEMCASEPALDEF.USAGE || '%') AS USAGE, cte.LISTINGOVERVIEWID, SUP.INTSUPPLIERNO AS SUPPLIERNO, SUP.DESCRIPTION AS SUPPLIERDESCRIPTION,cte.ReceivingCountry, cte.zRelevantMDM, cte.zSource, cte.zActive
FROM     cte  INNER JOIN
EKS.ITEMDIMENSION AS ITD ON cte.ITEMID = ITD.ITEMID AND ITD.CONTRACTPRICEVALIDITYID = cte.CONTRACTPRICEVALIDITYID INNER JOIN
EKS.SUPPLIER AS SUP ON cte.SUPPLIERNO = SUP.SUPPLIERNO INNER JOIN
EKS.LISTINGOVERVIEW ON EKS.LISTINGOVERVIEW.LISTINGOVERVIEWID = cte.LISTINGOVERVIEWID LEFT OUTER JOIN
EKS.LOHEADING AS LH ON LH.LOHEADINGID = EKS.LISTINGOVERVIEW.LOHEADINGID LEFT OUTER JOIN
EKS.TRANSLATION_INT AS TR_LH ON TR_LH.TRANSLATIONID = LH.DESCRIPTIONID LEFT OUTER JOIN
EKS.LOCATEGORY AS LC ON LC.LOCATEGORYID = EKS.LISTINGOVERVIEW.LOCATEGORYID and EKS.LISTINGOVERVIEW.LOCATEGORYID <> 4  LEFT OUTER JOIN
EKS.TRANSLATION_INT AS TR_LC ON TR_LC.TRANSLATIONID = LC.DESCRIPTIONID LEFT OUTER JOIN
EKS_CALCULATION.EKS_ZSM_EXCLUDELIST on EKS_CALCULATION.EKS_ZSM_EXCLUDELIST.ITEMNO =cte.ITEMNO AND
( ( SUP.INTSUPPLIERNO  = EKS_CALCULATION.EKS_ZSM_EXCLUDELIST.SUPPLIERNO AND EKS_CALCULATION.EKS_ZSM_EXCLUDELIST.LISTINGOVERVIEWID IS NULL ) OR ( cte.LISTINGOVERVIEWID = EKS_CALCULATION.EKS_ZSM_EXCLUDELIST.LISTINGOVERVIEWID AND EKS_CALCULATION.EKS_ZSM_EXCLUDELIST.SupplierNo IS NULL ) OR ( SUP.INTSUPPLIERNO  = EKS_CALCULATION.EKS_ZSM_EXCLUDELIST.SUPPLIERNO AND cte.LISTINGOVERVIEWID = EKS_CALCULATION.EKS_ZSM_EXCLUDELIST.LISTINGOVERVIEWID ) OR ( EKS_CALCULATION.EKS_ZSM_EXCLUDELIST.SupplierNo IS NULL AND EKS_CALCULATION.EKS_ZSM_EXCLUDELIST.LISTINGOVERVIEWID IS NULL ) ) AND EKS_CALCULATION.EKS_ZSM_EXCLUDELIST.REPORTNO = '027' LEFT OUTER JOIN
EKS.ITEMCASEPALDEF ON cte.CONTRACTPRICEVALIDITYID = EKS.ITEMCASEPALDEF.CONTRACTPRICEVALIDITYID
WHERE  ((EKS.ITEMCASEPALDEF.USAGE IS NULL) AND (cte.zMATKL <> '73') AND (cte.zMATKL <> '84') OR
(NOT (EKS.ITEMCASEPALDEF.USAGE BETWEEN 50 AND 120)) AND (cte.zMATKL <> '73') AND (cte.zMATKL <> '84') AND (CASE WHEN EKS.ITEMCASEPALDEF.USAGE = 0 AND lower(TR_LH.DESCRIPTION) LIKE '%dezentral%' THEN 0 WHEN EKS.ITEMCASEPALDEF.USAGE = 0 AND lower(TR_LC.DESCRIPTION) LIKE '%filialbelieferung%' THEN 0 ELSE 1 END = 1)) and  ( EKS_CALCULATION.EKS_ZSM_EXCLUDELIST.ITEMNO IS NULL )
);